C++Deck format main.cpp<pre><code>#include "slope.h"
using namespace slope;

Slideshow show;

int main(int argc, char** argv) {
    show.init("scene_demo", argc, argv);
    show &lt;&lt; Mesh::Add("spot.obj");
    show &lt;&lt; Shader::FromFile("occluded.frag")-&gt;at(CENTER);
    show.run();
    return 0;
}
</code></pre> deck.yaml<pre><code>slides:
  - frame:
      - mesh: spot.obj
      - shader: occluded.frag
        at: screen
</code></pre> occluded.frag<pre><code>#include &lt;camera.glsl&gt;
#include &lt;sdf.glsl&gt;
#include &lt;raymarch.glsl&gt;

float sceneSDF(vec3 p) {
    vec3 q = p - vec3(0.9, 0.3, 0.0);
    float a = sdSphere(q, 0.22);
    vec3 orbit = vec3(0.22 * sin(iTime), 0.22 * cos(iTime), 0.0);
    float b = sdSphere(q - orbit, 0.13);
    return opSmoothUnion(a, b, 0.15);
}

void main() {
    vec3 ro, rd; polyscopeRay(ro, rd);
    vec3 pos;
    if (marchScene(ro, rd, pos) &amp;&amp; visibleOverScene(pos)) {
        vec3 n = sceneNormal(pos);
        fragColor = vec4(shadeDefault(pos, n, rd, vec3(0.85, 0.25, 0.25), vec3(1.0)), 1.0);
    } else {
        discard;   // let the mesh show through instead
    }
}
</code></pre> When you need to activate the depth buffer <p>Currently, the scanner that checks if you need the depth buffer only reads the shader's own text, not what it pulls in through <code>#include</code>. A helper header of your own that wraps <code>visibleOverScene</code> internally is not detected, the shader that includes it has to call <code>shader-&gt;useSceneDepth()</code> from C++ instead, once.</p>
